const action=(a,label,ic='',cls='btn-secondary',data='')=>`<button type="button" class="btn ${cls}" data-a="${a}" ${data}>${ic?icon(ic):''}${label}</button>`;
const iconAction=(a,label,ic,data='')=>`<button type="button" class="icon-btn" aria-label="${esc(label)}" title="${esc(label)}" data-a="${a}" ${data}>${icon(ic)}</button>`;
const opt=(values,value)=>values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`;}).join('');
const field=(name,label,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(name,label,values,value='',extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${opt(values,value)}</select></label>`;
const notes=(value='')=>`<label class="field full"><span>Notas</span><textarea name="notes" maxlength="4000" rows="3">${esc(value)}</textarea></label>`;
const empty=(ic,title,desc,btn='')=>`<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${title}</h3><p>${desc}</p>${btn}</div>`;
const ident=id=>`data-id="${esc(id)}"`;
const personOptions=()=>[['','Sin asignar'],...state.people.map(x=>[x.id,x.name])];
const itemOptions=()=>[['','Sin vincular'],...state.items.map(x=>[x.id,x.name])];
const personName=id=>state.people.find(x=>x.id===id)?.name||'Sin asignar';
const itemName=id=>state.items.find(x=>x.id===id)?.name||'Sin vincular';
const avatar=name=>`<span class="avatar" title="${esc(name)}">${esc(name.slice(0,2).toUpperCase())}</span>`;
let state,route='today',menuOpen=false,installPrompt=null,swRegistration=null,storageError='',toastTimer,toastCallback,modalCleanup,dialogReturnFocus;
const views={today:['Resumen','grid'],tasks:['Tareas','tasks'],maintenance:['Mantenimiento','history'],items:['Inventario','box'],documents:['Documentos','file'],expenses:['Gastos','wallet'],shopping:['Compras','cart'],settings:['Mi hogar','settings']};
const ui={query:'',status:'pending',kind:'all',person:'all',area:'all',date:'',month:today().slice(0,7)};
