function safeFilename(name,extension=''){let n=String(name).replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').replace(/[. ]+$/g,'').slice(0,180)||'documento';if(extension&&!n.toLowerCase().endsWith(extension))n+=extension;return n;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=safeFilename(name);document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function documentFile(id,preview=false){const meta=state.documents.find(x=>x.id===id),file=await readFile(id);if(!meta||!file?.blob)throw Error('No se encuentra el archivo. Prueba a restaurar una copia completa.');const ext={'application/pdf':'.pdf','image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp'}[meta.type];
  if(!preview){download(file.blob,safeFilename(meta.name,ext));return;}
  const url=URL.createObjectURL(file.blob);
  dialog(esc(meta.name),`${meta.type==='application/pdf'?`<iframe class="preview-pdf" src="${url}" sandbox title="Vista previa del PDF"></iframe><p class="subtle-note">Si el navegador no muestra el PDF, descárgalo para abrirlo.</p>`:`<img class="preview-image" src="${url}" alt="${esc(meta.name)}">`}${action('download-document','Descargar documento','download','btn-primary',ident(id))}`);
  modalCleanup=()=>URL.revokeObjectURL(url);
}
async function backup(){
  const snap=await snapshot();
  toast('Preparando la copia completa…');
  const bundle=await packSnapshot(snap);
  download(new Blob([JSON.stringify(bundle)],{type:'application/json'}),`HomeOps-404-copia-${today()}.json`);
  state=await markBackup(bundle.exportedAt);render();
  toast('Descarga solicitada. Comprueba que el archivo se ha guardado.');
}
