async function resetDialog(demo=false){const revision=state.revision;dialog(demo?'Empezar con tus datos':'Borrar datos locales',`<p class="notice warning">${demo?'Se eliminará el hogar de ejemplo, incluidos los cambios y documentos que hayas añadido a él.':'Se eliminarán todos los datos y documentos de HomeOps en este navegador.'} Guarda antes una copia si quieres conservarlos.</p>${action('backup','Descargar copia antes','download','btn-secondary')}<hr class="rule">${field('confirm','Escribe BORRAR para confirmar','','text','required autocomplete="off" pattern="BORRAR"')}`,async fd=>{if(val(fd,'confirm')!=='BORRAR')throw Error('Escribe BORRAR exactamente.');await commit(()=>emptyState(),'Hogar vacío. Ya puedes añadir tus datos.',{clear:true},revision);closeDialog();nav('today');},{label:'Borrar y empezar',danger:true});}

document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-a]');if(!b||b.disabled)return;const a=b.dataset.a,id=b.dataset.id;
  if(a==='modal-delete')return;
  try{
    switch(a){
      case 'nav':closeDialog();nav(b.dataset.view);break;
      case 'menu':menuOpen=!menuOpen;render();if(menuOpen)document.querySelector('.sidebar .nav-link')?.focus();break;
      case 'close':closeDialog();break;
      case 'quick-add':quickAdd();break;
      case 'new-task':editorTask();break;
      case 'new-maintenance':editorTask('','maintenance');break;
      case 'new-maintenance-record':editorMaintenanceRecord('',id||'');break;
      case 'edit-maintenance-record':editorMaintenanceRecord(id);break;
      case 'item-maintenance':editorTask('','maintenance',id);break;
      case 'edit-task':editorTask(id);break;
      case 'complete':b.disabled=true;await markComplete(id);break;
      case 'new-item':editorItem();break;
      case 'edit-item':editorItem(id);break;
      case 'detail-item':detailItem(id);break;
      case 'new-expense':editorExpense();break;
      case 'edit-expense':editorExpense(id);break;
      case 'new-document':editorDocument();break;
      case 'item-document':editorDocument('',id);break;
      case 'edit-document':editorDocument(id);break;
      case 'open-document':await documentFile(id,true);break;
      case 'download-document':await documentFile(id);break;
      case 'status':ui.status=b.dataset.status;render();break;
      case 'day':{const date=b.dataset.date;route='tasks';ui.status='pending';ui.kind='all';ui.person='all';ui.date=date;ui.query='';history.pushState(null,'','#tasks');render(true);break;}
      case 'clear-date':ui.date='';render();break;
      case 'calendar':await exportCalendar();break;
      case 'alerts':showAlerts();break;
      case 'help':showHelp();break;
      case 'budget':budgetDialog();break;
      case 'install':installDialog();break;
      case 'backup':b.disabled=true;await backup();break;
      case 'backup-encrypted':encryptedBackupDialog();break;
      case 'restore':restoreDialog();break;
      case 'expense-csv':expenseCSVDialog();break;
      case 'export-expenses':exportExpenses();break;
      case 'csv-template':exportExpenses(true);break;
      case 'export-items':download(new Blob([csv([['Nombre','Zona','Marca / modelo','Serie / matrícula','Compra','Fin garantía','Importe EUR','Notas'],...state.items.map(x=>[x.name,x.area,x.brand,x.serial,x.purchase,x.warranty,(x.price/100).toFixed(2),x.notes])])],{type:'text/csv;charset=utf-8'}),'HomeOps-404-inventario.csv');break;
      case 'share-shopping':await shareShopping();break;
      case 'download-shopping':download(new Blob([shoppingText()],{type:'text/plain;charset=utf-8'}),'HomeOps-404-compras.txt');break;
      case 'export-shopping':exportShopping();break;
      case 'import-shopping':importShopping();break;
      case 'goto-shopping':closeDialog();nav('shopping');break;
      case 'toggle-shopping':await commit(s=>{const x=s.shopping.find(x=>x.id===id);if(x)x.done=!x.done;});break;
      case 'delete-shopping':deleteRecord('shopping',id,state.shopping.find(x=>x.id===id)?.name||'Producto');break;
      case 'edit-shopping':{const x=state.shopping.find(x=>x.id===id);if(!x)break;const revision=state.revision;dialog('Editar producto',`${field('name','Producto',x.name,'text','required maxlength="160"')}${field('quantity','Cantidad',x.quantity,'text','maxlength="40"')}`,async fd=>{await commit(s=>updateRecord(s,'shopping',{...x,name:val(fd,'name'),quantity:val(fd,'quantity')},false),'Producto guardado.',{},revision);closeDialog();});break;}
      case 'clear-shopping':{const revision=state.revision;confirmAction('Quitar productos comprados','Se conservarán todos los productos pendientes.',async()=>{await commit(s=>{s.shopping=s.shopping.filter(x=>!x.done);},'Lista actualizada.',{},revision);},'Quitar comprados',true);break;}
      case 'delete-person':{const x=state.people.find(x=>x.id===id),revision=state.revision;if(!x)break;confirmAction('Eliminar persona',`${x.name}\nLas tareas y gastos se conservarán como «Sin asignar».`,async()=>{await commit(s=>{s.people=s.people.filter(x=>x.id!==id);for(const x of [...s.tasks,...s.expenses])if(x.personId===id)x.personId='';},'Persona eliminada.',{},revision);},'Eliminar persona',true);break;}
      case 'demo':closeDialog();if(isEmpty()){await commit(()=>sampleState(),'Hogar de ejemplo preparado.');}else toast('El ejemplo solo se puede cargar en un hogar vacío.',true);break;
      case 'clear-demo':await resetDialog(true);break;
      case 'reset':await resetDialog();break;
      case 'persist-storage':{if(!navigator.storage?.persist){toast('Este navegador no permite solicitar almacenamiento persistente. Conserva copias externas.');break;}const ok=await navigator.storage.persist();toast(ok?'Almacenamiento persistente concedido. Mantén tus copias externas.':'El navegador no lo ha concedido. La app sigue funcionando; guarda copias externas.');break;}
      case 'toast-action':{const fn=toastCallback;toastCallback=null;if(fn)await fn();break;}
      case 'update':if(modal.open){toast('Cierra el formulario antes de actualizar.');break;}if(swRegistration?.waiting)confirmAction('Actualizar HomeOps','Los datos guardados se conservarán. Cualquier texto sin guardar en un formulario se perderá.',async()=>{swRegistration.waiting.postMessage({type:'SKIP_WAITING'});},'Actualizar');break;
    }
  }catch(error){toast(error.message||'No se ha podido completar la operación.',true);}finally{if(b.isConnected)b.disabled=false;}
});
document.addEventListener('input',e=>{const el=e.target;if(['shopping-form','settings-form','person-form'].includes(el.form?.id)&&el.name){inlineDrafts[el.form.id]??={};inlineDrafts[el.form.id][el.name]=el.type==='checkbox'?el.checked:el.value;}if(el.id==='search'){ui.query=el.value;render();}});
document.addEventListener('change',e=>{const map={'kind-filter':'kind','person-filter':'person','area-filter':'area','month-filter':'month'};const key=map[e.target.id];if(key){if(key==='month'&&!/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value))return;ui[key]=e.target.value;render();}});
document.addEventListener('submit',async e=>{
  const form=e.target;if(!['shopping-form','settings-form','person-form','alert-settings-form'].includes(form.id))return;e.preventDefault();const fd=new FormData(form),button=form.querySelector('[type=submit]');button.disabled=true;
  try{
    if(form.id==='shopping-form'){const name=val(fd,'name');if(!name)throw Error('Escribe un producto.');await commit(s=>{s.shopping.push({id:uid(),name,quantity:val(fd,'quantity'),done:false});},'Producto añadido.');}
    if(form.id==='settings-form')await commit(s=>{s.settings.home=val(fd,'home');s.settings.budget=parseMoney(val(fd,'budget'));s.settings.largeText=fd.has('largeText');},'Preferencias guardadas.');
    if(form.id==='alert-settings-form')await commit(s=>{s.settings.alertDays=Number(val(fd,'alertDays'));s.settings.alertsEnabled=fd.has('alertsEnabled');},'Avisos guardados.');
    if(form.id==='person-form'){const name=val(fd,'name');if(!name)throw Error('Escribe un nombre.');if(state.people.some(x=>x.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('Ya existe una persona con ese nombre.');await commit(s=>{s.people.push({id:uid(),name});},'Persona añadida.');}
    delete inlineDrafts[form.id];render();if(form.id==='shopping-form')document.querySelector('#shopping-form [name=name]')?.focus();
  }catch(error){toast(error.message||'No se ha podido guardar.',true);}finally{if(button.isConnected)button.disabled=false;}
});
window.addEventListener('keydown',e=>{
  if(!menuOpen||modal.open)return;
  if(e.key==='Escape'){menuOpen=false;render();document.querySelector('.mobile-toggle')?.focus();}
  if(e.key==='Tab'){const buttons=[...document.querySelectorAll('.sidebar button')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
matchMedia('(max-width:780px)').addEventListener('change',()=>{menuOpen=false;render();});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);route=views[next]?next:'today';ui.query='';ui.date='';menuOpen=false;render(true);});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast('HomeOps instalada.');});
async function refresh(){if(!state)return;try{const next=await readState();if(next.revision!==state.revision){state=next;render();}}catch(e){storageError='No se han podido actualizar los datos. Vuelve a abrir la app sin borrar el almacenamiento.';render();}}
if(channel)channel.onmessage=()=>refresh();
window.addEventListener('focus',refresh);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh();});
window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());
async function setupOffline(){
  if(!('serviceWorker' in navigator)||!window.isSecureContext)return;
  try{let controlled=!!navigator.serviceWorker.controller,reloading=false;swRegistration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});if(swRegistration.waiting)render();swRegistration.addEventListener('updatefound',()=>{const worker=swRegistration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'){if(navigator.serviceWorker.controller)render();else toast('HomeOps preparada para abrirse sin conexión.');}});});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(controlled&&!reloading){reloading=true;location.reload();}controlled=true;});}catch{toast('No se ha podido preparar el modo sin conexión. Vuelve a abrir la app cuando tengas red.',true);}
}
async function init(){try{state=await readState();route=views[location.hash.slice(1)]?location.hash.slice(1):'today';render();setupOffline();if(!state.settings.setupComplete&&isEmpty())setTimeout(onboarding,180);}catch(error){document.getElementById('app').innerHTML=`<main class="boot"><h1>No podemos abrir tu hogar</h1><p>${esc(error.message||'El navegador no permite acceder al almacenamiento local.')}</p><p>No borres los datos del sitio. Prueba a cerrar otras pestañas, salir del modo privado o abrir el mismo navegador donde guardaste tu hogar.</p><p><button type="button" class="btn btn-primary" id="retry">Volver a intentar</button></p></main>`;document.getElementById('retry').onclick=()=>location.reload();}}
init();
